import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.vNSRaLQv.js";const m=JSON.parse('{"title":"fnOS 内核 Bug 补丁实验记录","description":"","frontmatter":{"title":"fnOS 内核 Bug 补丁实验记录","date":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"posts/fnos-kernel-bug-experiment-2.md","filePath":"posts/fnos-kernel-bug-experiment-2.md"}'),i={name:"posts/fnos-kernel-bug-experiment-2.md"};function s(l,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="fnos-内核-bug-补丁实验记录" tabindex="-1">fnOS 内核 Bug 补丁实验记录 <a class="header-anchor" href="#fnos-内核-bug-补丁实验记录" aria-label="Permalink to &quot;fnOS 内核 Bug 补丁实验记录&quot;">​</a></h1><h2 id="日期" tabindex="-1">日期 <a class="header-anchor" href="#日期" aria-label="Permalink to &quot;日期&quot;">​</a></h2><p>2026-09-01（第二轮）</p><h2 id="实验-尝试修复-redis-createcontainererror" tabindex="-1">实验：尝试修复 redis CreateContainerError <a class="header-anchor" href="#实验-尝试修复-redis-createcontainererror" aria-label="Permalink to &quot;实验：尝试修复 redis CreateContainerError&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>修复 redis pod 的 <code>system.trim_acl</code> xattr 错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Error: failed to create containerd container: taking runtime copy of volume:</span></span>
<span class="line"><span>failed to copy xattrs: failed to get xattr &quot;system.trim_acl&quot;</span></span>
<span class="line"><span>on /tmp/ctd-volume*/data: operation not supported</span></span></code></pre></div><h3 id="尝试方案" tabindex="-1">尝试方案 <a class="header-anchor" href="#尝试方案" aria-label="Permalink to &quot;尝试方案&quot;">​</a></h3><p>执行 <code>mount -o remount,trimacl /</code> 给根分区加上 trimacl 支持。</p><h3 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to &quot;结果&quot;">​</a></h3><p><strong>立刻触发 fnOS 内核 bug，SSH 断连，系统权限被锁坏。</strong></p><p>时间线：</p><ol><li><code>ssh fnos &quot;mount -o remount,trimacl /&quot;</code> → 返回 exit:0（成功）</li><li>同一 SSH 会话中后续命令 <code>/usr/bin/mount</code> 报 Permission denied</li><li>SSH 连接断开，无法重连</li><li>重启 fnos 后恢复正常</li></ol><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><ul><li><code>mount -o remount,trimacl /</code> 会触发 fnOS 内核的 umount 冲突检测</li><li>内核随即把关键文件权限锁死（/root/.ssh/、/vol1 等）</li><li><strong>任何涉及 trimacl 的 mount 操作都可能触发此 bug</strong></li><li>redis 的 <code>system.trim_acl</code> 问题<strong>目前无法修复</strong>，只能等飞牛内核补丁</li></ul><hr><h2 id="已清理的修补脚本" tabindex="-1">已清理的修补脚本 <a class="header-anchor" href="#已清理的修补脚本" aria-label="Permalink to &quot;已清理的修补脚本&quot;">​</a></h2><p>重启 fnos 后，已全部撤回之前部署的临时修复：</p><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><code>/usr/local/bin/fix-vol1-perms.sh</code></td><td>✅ 已删除</td></tr><tr><td><code>/usr/local/bin/k3s-start.sh</code></td><td>✅ 已删除</td></tr><tr><td><code>/etc/systemd/system/fix-vol1-perms.service</code></td><td>✅ 已删除</td></tr><tr><td><code>/etc/systemd/system/fix-vol1-perms-oneshot.service</code></td><td>✅ 已删除</td></tr><tr><td><code>/etc/systemd/system/fix-vol1-perms.timer</code></td><td>✅ 已删除</td></tr><tr><td><code>/etc/systemd/system/k3s.service.d/override.conf</code> (UMask=0022)</td><td>✅ 已删除</td></tr><tr><td><code>deploy/k3s/base/backend.yaml</code> initContainer (fix-resolv)</td><td>✅ 已移除</td></tr></tbody></table><hr><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><h3 id="集群" tabindex="-1">集群 <a class="header-anchor" href="#集群" aria-label="Permalink to &quot;集群&quot;">​</a></h3><ul><li>fnos: Ready (6.18.18.c952-trim)</li><li>laptop: Ready (6.12.95+deb13-amd64)</li></ul><h3 id="服务" tabindex="-1">服务 <a class="header-anchor" href="#服务" aria-label="Permalink to &quot;服务&quot;">​</a></h3><ul><li>所有 Go 后端服务：Running（<strong>无 initContainer，正常运行</strong>）</li><li>redis master：CreateContainerError（xattr 问题，无法修复）</li><li>redis replica：Running</li><li>飞牛 nginx 管理面板：正常</li></ul><h3 id="关键发现" tabindex="-1">关键发现 <a class="header-anchor" href="#关键发现" aria-label="Permalink to &quot;关键发现&quot;">​</a></h3><ol><li>重启后 resolv.conf 权限正常（0644），Go 服务不需要 initContainer 也能正常运行</li><li>内核 bug 需要时间触发——重启后不会立刻出现</li><li><code>mount -o remount,trimacl /</code> 会<strong>立即</strong>触发 bug</li><li>k3s 重启后不会自动拉起，需要手动 <code>systemctl start k3s</code></li></ol><hr><h2 id="待办" tabindex="-1">待办 <a class="header-anchor" href="#待办" aria-label="Permalink to &quot;待办&quot;">​</a></h2><ol><li>等飞牛发布修复内核</li><li>redis 问题等内核修复后自然解决</li><li>考虑给 k3s 配置 <code>Restart=always</code> + <code>RestartSec=5</code> 确保自动恢复</li></ol>`,30)])])}const p=t(i,[["render",s]]);export{m as __pageData,p as default};
